        <section class="clinical-detail-card"><div class="clinical-detail-card-heading"><i class="bi bi-calendar2-week" aria-hidden="true"></i><div><h2>Appointment context</h2><p>Scheduled and recorded visit information.</p></div></div><dl class="clinical-detail-list"><div><dt>Doctor</dt><dd><?= esc($doctorName ?: 'Not provided') ?><small><?= esc($consultation['doctor_code'] ?? 'Code unavailable') ?></small></dd></div><div><dt>Clinic</dt><dd><?= esc($value($consultation['clinic_name'] ?? '')) ?></dd></div><div><dt>Visit date / time</dt><dd><?= esc(rootins_format_date($consultation['consultation_date'] ?? '') ?: 'Not provided') ?> · <?= esc(rootins_format_time($consultation['consultation_time'] ?? '') ?: 'Time not recorded') ?></dd></div><div><dt>Appointment</dt><dd><?= esc($value($consultation['appointment_number'] ?? '')) ?><?php if (!empty($consultation['appointment_date'])): ?><small><?= esc(rootins_format_date($consultation['appointment_date'])) ?> <?= esc(rootins_format_time($consultation['appointment_time'] ?? '')) ?></small><?php endif; ?></dd></div><div><dt>Service / queue</dt><dd><?= esc($value($consultation['service_name'] ?? '')) ?><?php if (!empty($consultation['queue_position'])): ?><small>Queue <?= esc((string) $consultation['queue_position']) ?></small><?php endif; ?></dd></div><div><dt>Follow-up date</dt><dd><?= esc(rootins_format_date($consultation['follow_up_date'] ?? '') ?: 'Not provided') ?></dd></div></dl></section>
    </div>
    <section class="clinical-detail-card clinical-detail-wide"><div class="clinical-detail-card-heading"><i class="bi bi-clipboard2-pulse" aria-hidden="true"></i><div><h2>Clinical record</h2><p>Chief complaints, diagnoses, advice, tests, diet, and treatment notes.</p></div></div><div class="clinical-narrative-grid"><article><h3>Chief complaint</h3><p><?= $clinicalText($consultation['chief_complaint'] ?? '') ?></p></article><article><h3>Clinical notes</h3><p><?= $clinicalText($consultation['clinical_notes'] ?? '') ?></p></article><article><h3>Diagnoses</h3><p><?= $clinicalText($consultation['diagnosis'] ?? '') ?></p></article><article><h3>Advice and treatment plan</h3><p><?= $clinicalText($consultation['treatment_plan'] ?? '') ?></p></article><article><h3>Diagnostic tests</h3><p><?= $clinicalText($consultation['diagnostic_tests'] ?? '') ?></p></article><article><h3>Diet plan</h3><p><?= $clinicalText($consultation['diet_plan'] ?? '') ?></p></article></div></section>
